body:
It seems there's a race condition when using shared connections. The same connection data gets used in two contexts and thus results in a segmentation fault. Here is an example that reproduces this issue.

These settings help reproduce the issue faster:
```
curl_easy_setopt(curl, CURLOPT_TCP_KEEPALIVE, 1);
// this simulates non-responsive DNS server
curl_easy_setopt(curl, CURLOPT_DNS_SERVERS, "127.127.127.127");
```

I use libcurl 7.63.0 together with c-ares 1.15.0 and openssl 1.0.2q...but it shouldn't matter as I can see during debugging that the same connection data gets used in two connection contexts and that results in a crash.

### I did this
```
#include <stdio.h>
#include <pthread.h>
#include <curl/curl.h>
#include <openssl/ssl.h>
#include <openssl/crypto.h>


#define URL "https://doesnt.really.matter.com/"

/* number of threads to fire up in parallel */
#define NUM_THREADS 67

/* how many times each URL is transferred per thread */
#define URL_ITERATIONS 11235

static size_t m_numLocks = 0;
static pthread_mutex_t *m_lockarray = NULL;
static pthread_mutex_t connlock;

static size_t write_db(void *ptr, size_t size, size_t nmemb, void *data)
{
  /* not interested in the downloaded bytes, return the size */
  (void)ptr;  /* unused */
  (void)data; /* unused */
  return (size_t)(size * nmemb);
}

static void lock_cb(CURL *handle, curl_lock_data data,
                    curl_lock_access access, void *userptr)
{
  (void)access; /* unused */
  (void)userptr; /* unused */
  (void)handle; /* unused */
  (void)data; /* unused */
  pthread_mutex_lock(&connlock);
}

static void unlock_cb(CURL *handle, curl_lock_data data,
                      void *userptr)
{
  (void)userptr; /* unused */
  (void)handle;  /* unused */
  (void)data;    /* unused */
  pthread_mutex_unlock(&connlock);
}

static void init_locks(void)
{
  pthread_mutex_init(&connlock, NULL);
}

static void kill_locks(void)
{
  pthread_mutex_destroy(&connlock);
}

static void SSL_CRYPTO_Lock_Handler(int mode, int index, const char *file, int line)
{
  if(index < 0 || (size_t)index >= m_numLocks)
    return;
  if(mode & CRYPTO_LOCK) {
    pthread_mutex_lock(&(m_lockarray[index]));
  } else {
    pthread_mutex_unlock(&(m_lockarray[index]));
  }
}

static unsigned long SSL_CRYPTO_GetThreadId(void)
{
  return (unsigned long)pthread_self();
}

static void SSL_InitLocks(void)
{
  m_numLocks = CRYPTO_num_locks();
  m_lockarray = (pthread_mutex_t *)OPENSSL_malloc(m_numLocks * sizeof(pthread_mutex_t));
  for(size_t i = 0; i<m_numLocks; ++i)
    pthread_mutex_init(&(m_lockarray[i]), NULL);

  CRYPTO_set_id_callback(SSL_CRYPTO_GetThreadId);
  CRYPTO_set_locking_callback(SSL_CRYPTO_Lock_Handler);
}

static void SSL_FreeLocks(void)
{
  if(!m_lockarray)
    return;

  CRYPTO_set_id_callback(NULL);
  CRYPTO_set_locking_callback(NULL);

  size_t num = m_numLocks;
  m_numLocks = 0;
  for(size_t i = 0; i<num; ++i)
    pthread_mutex_destroy(&(m_lockarray[i]));
  OPENSSL_free(m_lockarray);
  m_lockarray = NULL;
}

struct initurl {
  const char *url;
  CURLSH *share;
  int threadno;
};

static void *run_thread(void *ptr)
{
  struct initurl *u = (struct initurl *)ptr;
  int i;

  for(i = 0; i < URL_ITERATIONS; i++) {
    CURL *curl = curl_easy_init();
    curl_easy_setopt(curl, CURLOPT_URL, u->url);
    curl_easy_setopt(curl, CURLOPT_VERBOSE, 0L);
    curl_easy_setopt(curl, CURLOPT_SHARE, u->share);
    curl_easy_setopt(curl, CURLOPT_MAXCONNECTS, 64);

    // if this is disabled it just takes longer to reproduce the segmentation fault
    curl_easy_setopt(curl, CURLOPT_TCP_KEEPALIVE, 1);

    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_db);

    // this simulates non-responsive server...can be disabled but it just takes longer to reproduce the segmentation fault
    CURLcode code = curl_easy_setopt(curl, CURLOPT_DNS_SERVERS, "127.127.127.127");
    if(code != CURLE_OK) {
      fprintf(stderr, "CURL doesn't have CURLOPT_DNS_SERVERS support!\n");
    }

    curl_easy_perform(curl); /* ignores error */
    curl_easy_cleanup(curl);
    fprintf(stderr, "Thread %d transfer %d\n", u->threadno, i);
  }

  return NULL;
}

int main(void)
{
  pthread_t tid[NUM_THREADS];
  int i;
  int error;
  CURLSH *share;
  struct initurl url[NUM_THREADS];

  SSL_InitLocks();

  curl_global_init(CURL_GLOBAL_ALL);

  share = curl_share_init();
  curl_share_setopt(share, CURLSHOPT_LOCKFUNC, lock_cb);
  curl_share_setopt(share, CURLSHOPT_UNLOCKFUNC, unlock_cb);
  curl_share_setopt(share, CURLSHOPT_SHARE, CURL_LOCK_DATA_DNS);
  curl_share_setopt(share, CURLSHOPT_SHARE, CURL_LOCK_DATA_CONNECT);

  init_locks();

  for(i = 0; i< NUM_THREADS; i++) {
    url[i].url = URL;
    url[i].share = share;
    url[i].threadno = i;
    error = pthread_create(&tid[i], NULL, run_thread, &url[i]);
    if(0 != error)
      fprintf(stderr, "Couldn't run thread number %d, errno %d\n", i, error);
    else
      fprintf(stderr, "Thread %d, gets %s\n", i, URL);
  }

  /* now wait for all threads to terminate */
  for(i = 0; i< NUM_THREADS; i++) {
    error = pthread_join(tid[i], NULL);
    fprintf(stderr, "Thread %d terminated\n", i);
  }

  kill_locks();

  curl_share_cleanup(share);
  curl_global_cleanup();

  SSL_FreeLocks();

  return 0;
}
```
### I expected the following
I expected that the application does not crash and that connections are reused.

### curl/libcurl version
7.63.0

### operating system
2 different systems: Linux x86 and Linux ARM
